"""
Builds benchmarks/waterfall.bb with blitzcc, runs it and prints the frame times and what the frames cost: a river that falls
over a cliff, made of thousands of see-through sprites. The result is also saved as JSON (and added to a CSV) in benchmarks/results/.

    python3 benchmarks/waterfall.py [--blitzcc PATH] [--sprites N] [--frames N] [--seed N] [--size WxH]
                                     [--debug] [--profile] [--label NAME] [--shot FILE] [--no-save]

--sprites defaults to $BENCH_SPRITES or 5000, --frames to $BENCH_FRAMES or 300; "--sprites 50000" is the heavy run, and
"--quick" is 500 sprites and 30 frames for a look whether it works. -d builds without optimization (which BLITZ_FPS
profiling needs together with --profile); the build configuration is part of the result so runs are not mixed up.

The original Blitz3D works too, so that its speed can be compared: --blitzcc C:\\Blitz3D\\bin\\blitzcc.exe (BLITZPATH is set to the
folder with bin\\ in it unless it is set). It has no -O3 and no --profile, and no draw counters (they are 0), and it can have at most 16383 sprites.

Without a display the program runs under xvfb-run, which with Mesa means llvmpipe: the times are then mostly the CPU
rasterizing and only a smoke test. The counts (draws, triangles) are exact on any GPU.
"""
import argparse
import csv
import datetime
import json
import os
import platform
import re
import shutil
import subprocess
import sys
import tempfile

# Most sprites the original Blitz3D can have: they share one vertex buffer, 4 vertices each, and Direct3D 7 buffers hold at most 65535 vertices.
ORIGINAL_MAX_SPRITES = 16383
HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)


# Direct3D 7 limits the window to 2048 in each direction (measured on Areldir: 2048x2048 works, 2049x1080 and 500x3000 fail): the original Blitz3D then stops with
# "Unable to create 3D Scene".
ORIGINAL_MAX_SIZE = 2048

def find_compiler(given):
    if given:
        return given
    for candidate in (os.path.join(ROOT, "build", "code_compiler", "blitzcc"), os.path.join(ROOT, "build", "code_compiler", "blitzcc.exe"),
                      os.path.join(ROOT, "build", "distrib", "bin", "blitzcc.exe")):
        if os.path.isfile(candidate):
            return candidate
    return shutil.which("blitzcc") or sys.exit("blitzcc not found, build it or pass --blitzcc.")


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--blitzcc")
    parser.add_argument("--sprites", type=int, default=int(os.environ.get("BENCH_SPRITES", 5000)))
    parser.add_argument("--frames", type=int, default=int(os.environ.get("BENCH_FRAMES", 300)))
    parser.add_argument("--seed", type=int, default=int(os.environ.get("BENCH_SEED", 1)))
    parser.add_argument("--size", default=os.environ.get("BENCH_SIZE", "640x360"))
    parser.add_argument("--quick", action="store_true", help="500 sprites, 30 frames")
    parser.add_argument("--static", action="store_true", help="the water stays where it starts, only the camera moves")
    parser.add_argument("--debug", action="store_true", help="build with -d (no optimization)")
    parser.add_argument("--profile", action="store_true", help="build with --profile, for BLITZ_FPS=1")
    parser.add_argument("--label", default="", help="name of this run in the result, such as the GPU")
    parser.add_argument("--shot", help="save the last frame to this file")
    parser.add_argument("--no-save", action="store_true", help="don't write benchmarks/results/")
    args = parser.parse_args()
    if args.quick:
        args.sprites, args.frames = 500, 30
    width, height = args.size.lower().split("x")

    compiler = find_compiler(args.blitzcc)
    # The original Blitz3D prints only a version number for -v and has no optimization level or profiling, BlitzLLVM prints
    # "Compiler version:...". The same program is built with either, so that their speeds can be compared.
    version = " ".join(subprocess.run([compiler, "-v"], capture_output=True, text=True).stdout.split())
    llvm = bool(re.search(r"Compiler version:20\d\d\.", version))
    flags = ["-d"] if args.debug else (["-O3"] if llvm else [])
    if args.profile and llvm:
        flags.append("--profile")
    if not llvm and args.sprites > ORIGINAL_MAX_SPRITES:
        sys.exit("The original Blitz3D can draw only %d sprites (they share one vertex buffer of 4 vertices each, and Direct3D 7 "
                 "buffers have at most 65535 vertices); use --sprites %d or less with it, or BlitzLLVM for more." % (ORIGINAL_MAX_SPRITES, ORIGINAL_MAX_SPRITES))
    if not llvm and (int(width) > ORIGINAL_MAX_SIZE or int(height) > ORIGINAL_MAX_SIZE):
        sys.exit("The original Blitz3D (Direct3D 7) cannot open a window above %dx%d, it stops with \"Unable to create 3D Scene\" (asked for %sx%s); "
                 "use --size %dx%d or less with it, or BlitzLLVM for larger windows." % (ORIGINAL_MAX_SIZE, ORIGINAL_MAX_SIZE, width, height, ORIGINAL_MAX_SIZE, ORIGINAL_MAX_SIZE))
    if not llvm:
        # The original compiler reads its runtime and libraries from BLITZPATH, the folder that has bin\ in it.
        os.environ.setdefault("BLITZPATH", os.path.dirname(os.path.dirname(os.path.abspath(compiler))))
        # Without BLITZPATH the original prints an error instead of its version.
        version = " ".join(subprocess.run([compiler, "-v"], capture_output=True, text=True).stdout.split())
    runner = [] if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY") or platform.system() == "Windows" else ["xvfb-run", "-a", "-s", "-screen 0 %sx%sx24" % (width, height)]
    if runner and not shutil.which("xvfb-run"):
        sys.exit("There is no display and no xvfb-run.")

    with tempfile.TemporaryDirectory() as directory:
        program = os.path.join(directory, "waterfall" + (".exe" if platform.system() == "Windows" else ""))
        # Compiled from a copy with the include of this compiler next to it, whatever folder the original compiler resolves
        # includes from.
        source = os.path.join(directory, "waterfall.bb")
        shutil.copy(os.path.join(HERE, "waterfall.bb"), source)
        shutil.copy(os.path.join(HERE, "waterfall_llvm.bi" if llvm else "waterfall_original.bi"), os.path.join(directory, "waterfall_counters.bi"))
        build = subprocess.run([compiler, "-q"] + flags + ["-o", program, source], cwd=directory, capture_output=True, text=True)
        if build.returncode != 0:
            sys.exit("Building the benchmark failed (exit code %d):\n%s" % (build.returncode, (build.stdout + build.stderr)[-2000:]))
        env = dict(os.environ, BENCH_SPRITES=str(args.sprites), BENCH_FRAMES=str(args.frames), BENCH_SEED=str(args.seed), BENCH_W=width, BENCH_H=height,
                   BENCH_FRAMETIMES=os.path.join(directory, "frametimes.txt"), BENCH_RESULT=os.path.join(directory, "result.txt"))
        if args.static:
            env["BENCH_STATIC"] = "1"
        if args.profile and llvm:
            env["BLITZ_FPS"] = "1"
        if args.shot:
            env["BENCH_SHOT"] = os.path.abspath(args.shot)
        print("Running %d sprites, %d frames, %sx%s, build %s" % (args.sprites, args.frames, width, height, " ".join(flags)), flush=True)
        result = subprocess.run(runner + [program], env=env, capture_output=True, text=True)
        output = result.stdout + result.stderr
        # The original Blitz3D has no stdout for a program, so the result is read from a file.
        line = None
        if os.path.isfile(env["BENCH_RESULT"]):
            line = next((l for l in open(env["BENCH_RESULT"]).read().splitlines() if "RESULT " in l), None)
        if result.returncode != 0 or line is None:
            sys.exit("The benchmark failed (exit code %d):\n%s" % (result.returncode, output[-2000:]))
        values = {k: float(v) for k, v in re.findall(r"(\w+)=([-+\d.eE]+)", line.split("RESULT ", 1)[1])}
        # With --profile the runtime reports the GPU time of the passes once a second (BLITZ_FPS=1), summed over the frames of that
        # second: the first second (creating the sprites) is left out, the others are averaged per frame.
        gpu = {}
        if args.profile and llvm:
            frames_shown = 0
            sums = {"scene": 0.0, "2d": 0.0, "copy": 0.0, "present": 0.0, "frame": 0.0}
            shown = None
            first = True
            for l in output.splitlines():
                m = re.match(r"fps: (\d+),", l)
                if m:
                    shown = int(m.group(1))
                    continue
                m = re.match(r"\s+gpu passes: scene ([\d.]+) ms, 2d ([\d.]+) ms, copy ([\d.]+) ms, present ([\d.]+) ms, frame ([\d.]+) ms", l)
                if m and shown:
                    if first:
                        first = False
                        continue
                    frames_shown += shown
                    for k, v in zip(sums, m.groups()):
                        sums[k] += float(v)
            if frames_shown:
                gpu = {"gpu_" + k + "_ms": v / frames_shown for k, v in sums.items()}
                gpu["gpu_frames"] = frames_shown
        frametimes = []
        if os.path.isfile(env["BENCH_FRAMETIMES"]):
            frametimes = [int(l) for l in open(env["BENCH_FRAMETIMES"]).read().split()]

    record = {
        "date": datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds"),
        "label": args.label,
        "compiler": version if llvm else "Blitz3D " + version,
        "build": " ".join(flags),
        "platform": platform.platform(),
        "display": "xvfb" if runner else "native",
        "blitz_fps_hint": "BLITZ_FPS=1 prints the runtime timers once a second" if args.profile else "",
        "result": values,
        "gpu": gpu,
    }
    print("\n  sprites     %12d%s" % (values["sprites"], " (static)" if args.static else ""))
    print("  created in  %12.0f ms" % values["create_ms"])
    print("  update      %12.2f ms/frame (moving the sprites, part of ms/frame)" % values["update_ms"])
    print("  ms/frame    avg %.2f  min %.2f  median %.2f  p95 %.2f  max %.2f" % (values["ms_avg"], values["ms_min"], values["ms_median"], values["ms_p95"], values["ms_max"]))
    print("  fps         %12.1f" % values["fps"])
    print("  per frame   %.0f triangles, %.0f draw calls, %.0f pipeline binds, %.0f texture binds, %.0f buffer binds"
          % (values["tris"], values["draws"], values["pipelines"], values["textures"], values["buffers"]))
    if gpu:
        print("  gpu         scene %.3f ms, 2d %.3f ms, frame %.3f ms per frame (%d frames, from BLITZ_FPS, summed GPU passes)" % (gpu["gpu_scene_ms"], gpu["gpu_2d_ms"], gpu["gpu_frame_ms"], gpu["gpu_frames"]))
    print("  build       %s (%s)" % (record["build"] or "no options", version or "unknown compiler"))

    if not args.no_save:
        out = os.path.join(HERE, "results")
        os.makedirs(out, exist_ok=True)
        stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
        name = "waterfall-%s-%d" % (stamp, args.sprites)
        with open(os.path.join(out, name + ".json"), "w") as f:
            json.dump(dict(record, frame_times_us=frametimes), f, indent=1)
        csv_path = os.path.join(out, "waterfall.csv")
        new = not os.path.isfile(csv_path)
        with open(csv_path, "a", newline="") as f:
            writer = csv.writer(f)
            if new:
                writer.writerow(["date", "label", "build", "display", "sprites", "frames", "seed", "static", "update_ms", "ms_avg", "ms_min", "ms_median", "ms_p95", "ms_max", "fps", "tris", "draws", "pipelines", "textures", "buffers", "gpu_scene_ms", "gpu_frame_ms"])
            writer.writerow([record["date"], args.label, record["build"], record["display"]] + [values[k] for k in ("sprites", "frames", "seed", "static", "update_ms", "ms_avg", "ms_min", "ms_median", "ms_p95", "ms_max", "fps", "tris", "draws", "pipelines", "textures", "buffers")] + [gpu.get("gpu_scene_ms", ""), gpu.get("gpu_frame_ms", "")])
        print("  saved       benchmarks/results/%s.json and waterfall.csv" % name)


main()
